import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"丽人行","description":"","frontmatter":{"title":"丽人行","date":"2026-11-27T00:00:00.000Z","seq":32,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 乐府》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"杜甫","source_book":"唐诗三百首","prev":{"text":"兵车行","link":"/blogs/唐诗三百首·乐府/兵车行.html"},"next":{"text":"哀江头","link":"/blogs/唐诗三百首·乐府/哀江头.html"}},"headers":[],"relativePath":"blogs/唐诗三百首·乐府/丽人行.md","filePath":"blogs/唐诗三百首·乐府/丽人行.md"}'),o={name:"blogs/唐诗三百首·乐府/丽人行.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="丽人行" tabindex="-1">丽人行 <a class="header-anchor" href="#丽人行" aria-label="Permalink to &quot;丽人行&quot;">​</a></h1><p class="poem-meta">唐 · 杜甫　·　乐府</p><div class="poem"><p class="poem-stanza">三月三日天气新，长安水边多丽人。</p><p class="poem-stanza">态浓意远淑且真，肌理细腻骨肉匀。</p><p class="poem-stanza">绣罗衣裳照暮春，蹙金孔雀银麒麟。</p><p class="poem-stanza">头上何所有？翠微盍叶垂鬓唇。</p><p class="poem-stanza">背后何所见？珠压腰衱稳称身。</p><p class="poem-stanza">就中云幕椒房亲，赐名大国虢与秦。</p><p class="poem-stanza">紫驼之峰出翠釜，水精之盘行素鳞。</p><p class="poem-stanza">犀箸厌饫久未下，鸾刀缕切空纷纶。</p><p class="poem-stanza">黄门飞鞚不动尘，御厨络绎送八珍。</p><p class="poem-stanza">箫鼓哀吟感鬼神，宾从杂遝实要津。</p><p class="poem-stanza">后来鞍马何逡巡，当轩下马入锦茵。</p><p class="poem-stanza">杨花雪落覆白苹，青鸟飞去衔红巾。</p><p class="poem-stanza">炙手可热势绝伦，慎莫近前丞相嗔！</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
